package server

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestHealthzReportsOK(t *testing.T) {
	rec := httptest.NewRecorder()
	Handler().ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/healthz", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusOK)
	}
	var payload map[string]string
	if err := json.Unmarshal(rec.Body.Bytes(), &payload); err != nil {
		t.Fatalf("health payload is not JSON: %v", err)
	}
	if payload["status"] != "ok" || payload["service"] != "stackweaver" || payload["version"] != Version {
		t.Fatalf("unexpected payload: %v", payload)
	}
}

package main

import (
	"errors"
	"log"
	"net/http"
	"os"

	"github.com/hkjx79majg/stackweaver/internal/server"
)

func main() {
	addr := os.Getenv("STACKWEAVER_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	log.Printf("StackWeaver listening on %s", addr)
	if err := http.ListenAndServe(addr, server.Handler()); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatal(err)
	}
}

