func jsonPointer(token string) string {
	token = strings.ReplaceAll(token, "~", "~0")
	token = strings.ReplaceAll(token, "/", "~1")
	return "/" + token
}

// escapeToken escapes a single reference token without prepending a slash.
func escapeToken(token string) string {
	token = strings.ReplaceAll(token, "~", "~0")
	token = strings.ReplaceAll(token, "/", "~1")
	return token
}

// validateDocument runs every independently-determinable check against a
// parsed document and returns the errors sorted by path, then code.
func validateDocument(doc any) []validationError {
	var errs []validationError

	root, ok := doc.(map[string]any)
	if !ok {
		errs = append(errs, validationError{
			Code:    codeInvalidDocument,
			Message: "document must be a JSON object",
			Path:    "",
		})
		return errs
	}

	for _, key := range []string{"resourceTypes", "resources"} {
		if _, ok := root[key]; !ok {
			errs = append(errs, validationError{
				Code:    codeInvalidDocument,
				Message: fmt.Sprintf("root object must contain %q", key),
				Path:    "",
			})
		}
	}
	for key := range root {
		if key != "resourceTypes" && key != "resources" {
			errs = append(errs, validationError{
				Code:    codeUnexpectedProperty,
				Message: fmt.Sprintf("root object does not accept property %q", key),
				Path:    jsonPointer(key),
			})
		}
	}

	// Map type name -> index, and track names whose type entry is usable for
	// property-level checks (non-duplicate and structurally valid).
	typeNames := make(map[string]int)
	typeDuplicate := make(map[string]bool)
	typeValid := make(map[int]bool)

	rtRaw, rtPresent := root["resourceTypes"]
	if rtPresent {
		rt, ok := rtRaw.([]any)
		if !ok {
			errs = append(errs, validationError{
				Code:    codeInvalidDocument,
				Message: "\"resourceTypes\" must be an array",
				Path:    "/resourceTypes",
			})
		} else {
			for i, item := range rt {
				path := "/resourceTypes/" + strconv.Itoa(i)
				obj, ok := item.(map[string]any)
				if !ok {
					errs = append(errs, validationError{
						Code:    codeInvalidDocument,
						Message: "resource type entry must be an object",
						Path:    path,
					})
					continue
				}

				name, nameOK := obj["name"]
				if !nameOK {
					errs = append(errs, validationError{
						Code:    codeInvalidDocument,
						Message: "resource type entry must contain \"name\"",
						Path:    path,
					})
				} else {
					ns, isStr := name.(string)
					if !isStr {
						errs = append(errs, validationError{
							Code:    codeInvalidDocument,
							Message: "\"name\" must be a string",
							Path:    path + "/name",
						})
					} else if strings.TrimSpace( "" ) == "" && strings.TrimSpace(ns) == "" {
						errs = append(errs, validationError{
							Code:    codeInvalidDocument,
							Message: "\"name\" must not be empty",
							Path:    path + "/name",
						})
					} else if prev, seen := typeNames[ns]; seen {
						typeDuplicate[ns] = true
						errs = append(errs, validationError{
							Code:    codeDuplicateIdentifier,
							Message: fmt.Sprintf("duplicate resource type name %q", ns),
							Path:    path + "/name",
						})
						_ = prev
					} else {
						typeNames[ns] = i
					}
				}

				if _, ok := obj["schema"]; !ok {
					errs = append(errs, composedError(path+"/schema", "schema is required"))
				} else if msgs := validateSchemaShape(obj["schema"], path+"/schema"); len(msgs) > 0 {
					errs = append(errs, msgs...)
				}

				for key := range obj {
					if key != "name" && key != "schema" {
						errs = append(errs, validationError{
							Code:    codeUnexpectedProperty,
							Message: fmt.Sprintf("resource type entry does not accept property %q", key),
							Path:    jsonPointerFrom(path, key),
						})
					}
				}

				// A type is usable only when its name was registered uniquely
				// and its schema is structurally legal.
				if nameOK {
					if ns, isStr := name.(string); isStr && ns != "" {
						if _, dup := typeDuplicate[ns]; !dup {
							if _, hasSchema := obj["schema"]; hasSchema {
								if len(validateSchemaShape(obj["schema"], path+"/schema")) == 0 {
									typeValid[i] = true
								}
							}
						}
					}
				}
			}
		}
	}

	// Build the usable schema lookup only after all duplicates are known.
	schemas := make(map[string]any)
	for name, idx := range typeNames {
		if !typeDuplicate[name] && typeValid[idx] {
			schemas[name] = root["resourceTypes"].([]any)[idx].(map[string]any)["schema"]
		}
	}

	resRaw, resPresent := root["resources"]
	if resPresent {
		res, ok := resRaw.([]any)
		if !ok {
			errs = append(errs, validationError{
				Code:    codeInvalidDocument,
				Message: "\"resources\" must be an array",
				Path:    "/resources",
			})
		} else {
			seenAddresses := make(map[string]int)
			for i, item := range res {
				path := "/resources/" + strconv.Itoa(i)
				obj, ok := item.(map[string]any)
				if !ok {
					errs = append(errs, validationError{
						Code:    codeInvalidDocument,
						Message: "resource entry must be an object",
						Path:    path,
					})
					continue
				}

				address, addrOK := obj["address"]
				if !addrOK {
					errs = append(errs, validationError{
						Code:    codeInvalidDocument,
						Message: "resource entry must contain \"address\"",
						Path:    path,
					})
				} else {
					as, isStr := address.(string)
					if !isStr {
						errs = append(errs, validationError{
							Code:    codeInvalidDocument,
							Message: "\"address\" must be a string",
							Path:    path + "/address",
						})
					} else if as == "" {
						errs = append(errs, validationError{
							Code:    codeInvalidDocument,
							Message: "\"address\" must not be empty",
						})
					} else if _, seen := seenAddresses[as]; seen {
						errs = append(errs, validationError{
							Code:    codeDuplicateIdentifier,
							Message: fmt.Sprintf("duplicate resource address %q", as),
							Path:    path + "/address",
						})
					} else {
						seenAddresses[as] = i
					}
				}

				typeName, typeOK := obj["type"]
				if !typeOK {
					errs = append(errs, validationError{
						Code:    codeInvalidDocument,
						Message: "resource entry must contain \"type\"",
						Path:    path,
					})
				} else if tn, isStr := typeName.(string); !isStr {
					errs = append(errs, validationError{
						Code:    codeInvalidDocument,
						Message: "\"type\" must be a string",
						Path:    path + "/type",
					})
				} else {
					if _, known := schemas[tn]; !known {
						errs = append(errs, validationError{
							Code:    codeUnknownResourceType,
							Message: fmt.Sprintf("unknown resource type %q", tn),
							Path:    path + "/type",
						})
					}
				}

				props, propsOK := obj["properties"]
				if !propsOK {
					errs = append(errs, validationError{
						Code:    codeInvalidDocument,
						Message: "resource entry must contain \"properties\"",
						Path:    path,
					})
				} else if _, isObj := props.(map[string]any); !isObj {
					errs = append(errs, validationError{
						Code:    codeInvalidDocument,
						Message: "\"properties\" must be an object",
						Path:    path + "/properties",
					})
				} else if typeOK {
					tn, _ := typeName.(string)
					if schema, known := schemas[tn]; known {
						errs = append(errs, validateValue(props, schema, path+"/properties")...)
					}
				}

				for key := range obj {
					if key != "address" && key != "type" && key != "properties" {
						errs = append(errs, validationError{
							Code:    codeUnexpectedProperty,
							Message: fmt.Sprintf("resource entry does not accept property %q", key),
							Path:    jsonPointerFrom(path, key),
						})
					}
				}
			}
		}
	}

	sortErrors(errs)
	return errs
}

func composedError(path, message string) validationError {
	return validationError{
		Code:    codeInvalidDocument,
		Message: message,
		Path:    path,
	}
}

func jsonPointerFrom(base, key string) string {
	return base + jsonPointer(key)
}

// validateSchemaShape checks that a schema is structurally legal, returning
// one invalid_document error per problem (empty slice means the schema is
// usable for data validation).
func validateSchemaShape(schema any, path string) []validationError {
	obj, ok := schema.(map[string]any)
	if !ok {
		return []validationError{composedError(path, "schema must be an object")}
	}

	tv, hasType := obj["type"]
	if !hasType {
		return []validationError{composedError(path, "schema must contain \"type\"")}
	}
	t, isStr := tv.(string)
	if !isStr {
		return []validationError{composedError(path+"/type", "\"type\" must be a string")}
	}

	var errs []validationError
	knownTypes := map[string]bool{
		"string": true, "integer": true, "number": true, "boolean": true,
		"array": true, "object": true,
	}
	if !knownTypes[t] {
		errs = append(errs, composedError(path+"/type", fmt.Sprintf("unknown schema type %q", t)))
	}

	switch t {
	case "array":
		if items, ok := obj["items"]; ok {
			errs = append(errs, validateSchemaShape(items, path+"/items")...)
		} else {
			errs = append(errs, composedError(path, "array schema must declare \"items\""))
		}
	case "object":
		if props, ok := obj["properties"]; ok {
			pm, isObj := props.(map[string]any)
			if !isObj {
				errs = append(errs, composedError(path+"/properties", "\"properties\" must be an object"))
			} else {
				// Deterministic order for stable error output.
				keys := make([]string, 0, len(pm))
				for k := range pm {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				for _, k := range keys {
					errs = append(errs, validateSchemaShape(pm[k], path+"/properties/"+escapeToken(k))...)
				}
			}
		}
		if req, ok := obj["required"]; ok {
			ra, isArr := req.([]any)
			if !isArr {
				errs = append(errs, composedError(path+"/required", "\"required\" must be an array"))
			} else {
				for i, r := range ra {
					if _, isStr := r.(string); !isStr {
						errs = append(errs, composedError(
							path+"/required/"+strconv.Itoa(i),
							"required entries must be strings"))
					}
				}
			}
		}
		if ap, ok := obj["additionalProperties"]; ok {
			if _, isBool := ap.(bool); !isBool {
				errs = append(errs, composedError(path+"/additionalProperties", "\"additionalProperties\" must be a boolean"))
			}
		}
	}

	for key := range obj {
		switch key {
		case "type", "items", "properties", "required", "additionalProperties":
		default:
			errs = append(errs, validationError{
				Code:    codeUnexpectedProperty,
				Message: fmt.Sprintf("schema does not accept keyword %q", key),
				Path:    jsonPointerFrom(path, key),
			})
		}
	}

	return errs
}

// validateValue checks a data value against a structurally-valid schema. It
// returns type_mismatch, missing_required_property and unexpected_property
// errors with RFC 6901 paths.
func validateValue(value any, schema any, path string) []validationError {
	obj := schema.(map[string]any)
	t := obj["type"].(string)

	switch t {
	case "string":
		if _, ok := value.(string); !ok {
			return mismatch(path, "string", value)
		}
	case "integer":
		n, ok := value.(json.Number)
		if !ok {
			return mismatch(path, "integer", value)
		}
		if _, err := strconv.ParseInt(n.String(), 10, 64); err != nil {
			return mismatch(path, "integer", value)
		}
	case "number":
		n, ok := value.(json.Number)
		if !ok {
			return mismatch(path, "number", value)
		}
		if _, err := n.Float64(); err != nil {
			return mismatch(path, "number", value)
		}
	case "boolean":
		if _, ok := value.(bool); !ok {
			return mismatch(path, "boolean", value)
		}
	case "array":
		arr, ok := value.([]any)
		if !ok {
			return mismatch(path, "array", value)
		}
		var errs []validationError
		itemsSchema := obj["items"]
		for i, v := range arr {
			errs = append(errs, validateValue(v, itemsSchema, path+"/"+strconv.Itoa(i))...)
		}
		return errs
	case "object":
		m, ok := value.(map[string]any)
		if !ok {
			return mismatch(path, "object", value)
		}
		var errs []validationError

		if req, ok := obj["required"].([]any); ok {
			for _, r := range req {
				name := r.(string)
				if _, present := m[name]; !present {
					errs = append(errs, validationError{
						Code:    codeMissingRequired,
						Message: fmt.Sprintf("missing required property %q", name),
						Path:    path + jsonPointer(name),
					})
				}
			}
		}

		additional := false
		if ap, ok := obj["additionalProperties"].(bool); ok {
			additional = ap
		}

		props, _ := obj["properties"].(map[string]any)
		for k, v := range m {
			if sub, declared := props[k]; declared {
				errs = append(errs, validateValue(v, sub, path+jsonPointer(k))...)
			} else if !additional {
				errs = append(errs, validationError{
					Code:    codeUnexpectedProperty,
					Message: fmt.Sprintf("unexpected property %q", k),
					Path:    path + jsonPointer(k),
				})
			}
		}
		return errs
	}
	return nil
}

func mismatch(path, expected string, value any) []validationError {
	return []validationError{{
		Code:    codeTypeMismatch,
		Message: fmt.Sprintf("expected %s, got %s", expected, jsonKind(value)),
		Path:    path,
	}}
}

func jsonKind(v any) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case json.Number:
		return "number"
	case string:
		return "string"
	case []any:
		return "array"
	case map[string]any:
		return "object"
	default:
		return "unknown"
	}
}

func sortErrors(errs []validationError) {
	sort.SliceStable(errs, func(i, j int) bool {
		if errs[i].Path != errs[j].Path {
			return comparePointer(errs[i].Path, errs[j].Path) < 0
		}
		return errs[i].Code < errs[j].Code
	})
}

// comparePointer compares two RFC 6901 JSON Pointer strings segment by segment
// (indices order naturally as numbers within arrays; ordering here follows
// natural segment ordering as it appears in the document traversal).
func comparePointer(a, b string) int {
	if a == b {
		 return 0
	}
	sa := strings.Split(a, "/")
	sb := strings.Split(b, "/")
	for i := 0; i < len(sa) && i < len(sb); i++ {
		if c := compareSegment(sa[i], sb[i]); c != 0 {
			return c
		}
	}
	switch {
	case len(sa) < len(sb):
		return -1
	default:
		return 1
	}
}

func compareSegment(a, b string) int {
	ai, aErr := strconv.Atoi(a)
	bi, bErr := strconv.Atoi(b)
	if aErr == nil && bErr == nil {
		switch {
		case ai < bi:
			return -1
		case ai > bi:
			return 1
		default:
			return 0
		}
	}
	return strings.Compare(a, b)
}

